20	import { withTenantAuth, type TenantApiContext } from "@/lib/api";
21	import { withTenant } from "@/lib/with-tenant";
22	import { createAuditEntry } from "@/lib/services/audit";
23	import { membershipYearExpiry, parseDateWithTimezone } from "@/lib/timezone";
24	
25	export const POST = withTenantAuth(
26	  async ({ auth, tenant, request }: TenantApiContext) => {
27	    // Check manual_add permission
28	    const { checkPermission } = await import("@/lib/permissions");
29	    const permResult = checkPermission(auth, tenant.id, Permission.MANUAL_ADD);
30	    if (!permResult.granted) {
31	      return NextResponse.json({ error: permResult.reason }, { status: 403 });
32	    }
33	    const body = await request.json();
34	    const parsed = manualAddCredentialSchema.safeParse(body);
35	    if (!parsed.success) {
36	      return NextResponse.json(
37	        { error: "Validation failed", details: parsed.error.flatten() },
38	        { status: 400 }
39	      );
40	    }
41	
42	    const {
43	      ownerId,
44	      credentialTypeId: explicitCredentialTypeId,
45	      accessLevelId: explicitAccessLevelId,
46	      serialNumber,
47	      accessStartsAt,
48	      expiresAt,
49	      stage,
50	    } = parsed.data;
51	
52	    const settings = tenant.settings as TenantSettings;
53	    const allowFobCreationAtProgramming =
54	      settings.allowFobCreationAtProgramming ?? false;
55	
56	    const result = await withTenant(tenant.id, async (tx) => {
57	      const [membership] = await tx
58	        .select()
59	        .from(tenantMemberships)
60	        .where(
61	          and(
62	            eq(tenantMemberships.userId, ownerId),
63	            eq(tenantMemberships.tenantId, tenant.id)
64	          )
65	        )
66	        .limit(1);
67	
68	      if (!membership) {
69	        throw new Error("Owner is not a member of this organisation");
70	      }
71	
72	      // Resolve accessLevelId: use explicit if provided, otherwise inherit from membership
73	      const accessLevelId = explicitAccessLevelId ?? membership.accessLevelId;
74	
75	      // If assigning from an existing unallocated fob, infer credentialTypeId from the fob
76	      let credentialTypeId = explicitCredentialTypeId;
77	      if (!credentialTypeId) {
78	        const [existingFob] = await tx
79	          .select({ credentialTypeId: credentials.credentialTypeId })
80	          .from(credentials)
81	          .where(eq(credentials.serialNumber, serialNumber))
82	          .limit(1);
83	        credentialTypeId = existingFob?.credentialTypeId;
84	      }
85	
86	      if (!credentialTypeId) {
87	        throw new Error(
88	          "Credential type is required when not assigning an existing fob"
89	        );
90	      }
91	
92	      const [ct] = await tx
93	        .select()
94	        .from(credentialTypes)
95	        .where(
96	          and(
97	            eq(credentialTypes.id, credentialTypeId),
98	            eq(credentialTypes.isActive, true)
99	          )
100	        )
101	        .limit(1);
102	
103	      if (!ct) {
104	        throw new Error("Credential type not found or inactive");
105	      }
106	
107	      // Look up access level name for the response
108	      let accessLevelName: string | null = null;
109	      if (accessLevelId) {
110	        const [al] = await tx
111	          .select()
112	          .from(accessLevels)
113	          .where(
114	            and(
115	              eq(accessLevels.id, accessLevelId),
116	              eq(accessLevels.isActive, true)
117	            )
118	          )
119	          .limit(1);
120	
121	        if (!al) {
122	          throw new Error("Access level not found or inactive");
123	        }
124	        accessLevelName = al.name;
125	      }
126	
127	      const now = new Date();
128	
129	      let parsedAccessStartsAt: Date | undefined;
130	      if (accessStartsAt) {
131	        parsedAccessStartsAt = parseDateWithTimezone(
132	          accessStartsAt,
133	          tenant.timezone
134	        );
135	      }
136	
137	      let parsedExpiresAt: Date | undefined;
138	      if (expiresAt) {
139	        parsedExpiresAt = parseDateWithTimezone(expiresAt, tenant.timezone);
140	      }
141	
142	      // --- Calculate expiry for pickup/issued stages ---
143	      let calculatedExpiresAt: Date | null = parsedExpiresAt ?? null;
144	
145	      if (
146	        (stage === "pickup" || stage === "issued") &&
147	        !parsedExpiresAt
148	      ) {
149	        // Check if staff or board member
150	        const isStaffOrBoard =
151	          membership.isStaff || membership.isBoardMember;
152	
153	        if (!isStaffOrBoard) {
154	          // Membership-year expiry (Sep 1 rollover) in the tenant's timezone
155	          calculatedExpiresAt = membershipYearExpiry(
156	            tenant.timezone ?? "Australia/Melbourne"
157	          );
158	        }
159	        // Staff/board: calculatedExpiresAt stays null
160	      }
161	
162	      // --- Determine request and credential status based on stage ---
163	      const requestStatusMap: Record<string, string> = {
164	        programming: RequestStatus.AWAITING_PROGRAMMING,
165	        pickup: RequestStatus.AWAITING_PICKUP,
166	        issued: RequestStatus.ISSUED,
167	      };
168	      const credStatusMap: Record<string, string> = {
169	        programming: CredentialStatus.PENDING_PROGRAMMING,
170	        pickup: CredentialStatus.ACTIVE,
171	        issued: CredentialStatus.ACTIVE,
172	      };
173	      const requestStatus = requestStatusMap[stage];
174	      const credStatus = credStatusMap[stage];
175	
176	      // Create the tracking request
177	      const [fobRequest] = await tx
178	        .insert(fobRequests)
179	        .values({
180	          tenantId: tenant.id,
181	          requesterId: ownerId,
182	          credentialTypeId,
183	          accessLevelId: accessLevelId ?? null,
184	          requestType: RequestType.NEW,
185	          status: requestStatus,
186	          serialNumber,
187	          submittedAt: now,
188	          credentialExpiresAt: calculatedExpiresAt,
189	          ...(stage === "pickup" || stage === "issued"
190	            ? { programmedAt: now, programmedBy: auth.user.id }
191	            : {}),
192	          ...(stage === "issued"
193	            ? { issuedAt: now, issuedBy: auth.user.id }
194	            : {}),
195	        })
196	        .returning();
197	
198	      // Check if a credential with this serial + type already exists (unallocated or deactivated)
199	      const [existingFob] = await tx
200	        .select({
201	          id: credentials.id,
202	          ownerId: credentials.ownerId,
203	          status: credentials.status,
204	        })
205	        .from(credentials)
206	        .where(
207	          and(
208	            eq(credentials.credentialTypeId, credentialTypeId),
209	            eq(credentials.serialNumber, serialNumber),
210	            or(
211	              isNull(credentials.ownerId),
212	              eq(credentials.status, "deactivated")
213	            )
214	          )
215	        )
216	        .limit(1);
217	
218	      // Guard: if no existing fob and creation not allowed, error out
219	      if (!existingFob && !allowFobCreationAtProgramming) {
220	        throw new Error(
221	          "No existing fob found with this serial number. Fob creation is not enabled for this organisation."
222	        );
223	      }
224	
225	      let credential;
226	      let wasReassignment = false;
227	      const previousOwnerId = existingFob?.ownerId ?? null;
228	
229	      const credValues = {
230	        ownerId,
231	        credentialTypeId,
232	        accessLevelId: accessLevelId ?? null,
233	        requestId: fobRequest.id,
234	        status: credStatus,
235	        issuedAt: now,
236	        accessStartsAt: parsedAccessStartsAt ?? null,
237	        expiresAt: calculatedExpiresAt,
238	        updatedAt: now,
239	        deactivatedAt: null,
240	        deactivatedBy: null,
241	        deactivationReason: null,
242	      };
243	
244	      if (existingFob) {
245	        wasReassignment =
246	          previousOwnerId !== null && previousOwnerId !== ownerId;
247	
248	        const [updated] = await tx
249	          .update(credentials)
250	          .set(credValues)
251	          .where(eq(credentials.id, existingFob.id))
252	          .returning();
253	        credential = updated;
254	      } else {
255	        const [created] = await tx
256	          .insert(credentials)
257	          .values({
258	            tenantId: tenant.id,
259	            serialNumber,
260	            ...credValues,
261	          })
262	          .returning();
263	        credential = created;
264	      }
265	
266	      // Update membership access level if one was set (either from rules or manual)
267	      if (accessLevelId) {
268	        await tx
269	          .update(tenantMemberships)
270	          .set({ accessLevelId, updatedAt: now })
271	          .where(
272	            and(
273	              eq(tenantMemberships.userId, ownerId),
274	              eq(tenantMemberships.tenantId, tenant.id)
275	            )
276	          );
277	      }
278	
279	      // --- Audit entries ---
280	
281	      // 1. Reassignment audit (existing fob with different previous owner)
282	      if (wasReassignment) {
283	        await createAuditEntry(tx, {
284	          tenantId: tenant.id,
285	          entityType: AuditEntityType.CREDENTIAL,
286	          entityId: credential.id,
287	          action: AuditAction.STATUS_CHANGE,
288	          fromState: "deactivated",
289	          toState: credStatus,
290	          actorId: auth.user.id,
291	          actorType: "user",
292	          metadata: {
293	            description: "Credential reassigned",
294	            previousOwnerId,
295	            newOwnerId: ownerId,
296	            reason: "manual_add",
297	          },
298	        });
299	      }
300	
301	      // 2. Activation audit (pickup or issued)
302	      if (stage === "pickup" || stage === "issued") {
303	        await createAuditEntry(tx, {
304	          tenantId: tenant.id,
305	          entityType: AuditEntityType.CREDENTIAL,
306	          entityId: credential.id,
307	          action: wasReassignment
308	            ? AuditAction.UPDATE
309	            : AuditAction.STATUS_CHANGE,
310	          toState: CredentialStatus.ACTIVE,
311	          actorId: auth.user.id,
312	          actorType: "user",
313	          metadata: {
314	            description: "Credential activated",
315	            expiresAt: calculatedExpiresAt?.toISOString() ?? null,
316	            stage,
317	          },
318	        });
319	      }
320	
321	      // 3. New allocation audit (no existing fob - brand new credential)
322	      if (!existingFob) {
323	        await createAuditEntry(tx, {
324	          tenantId: tenant.id,
