40	type ActiveAction =
41	  | { type: "add" }
42	  | { type: "revoke"; credentialId: string }
43	  | { type: "swap"; credentialId: string; currentCredentialTypeName: string | null; currentAccessLevelName: string | null }
44	  | null;
45	
46	export function CredentialActions({
47	  tenantSlug,
