49	  credentials: memberCreds,
50	  credentialTypes,
51	  accessLevels,
52	  availableFobs,
53	  allowFobCreationAtProgramming,
54	  canProgram,
55	  canManualAdd,
56	  memberAccessLevelName,
57	}: Props) {
58	  const router = useRouter();
59	  const [activeAction, setActiveAction] = useState<ActiveAction>(null);
60	
61	  const activeCreds = memberCreds.filter((c) => c.status === "active");
62	  const inactiveCreds = memberCreds.filter((c) => c.status !== "active");
63	
64	  return (
65	    <Card>
66	      <CardHeader>
67	        <div className="flex items-center justify-between">
68	          <CardTitle className="text-base">
69	            Credentials ({memberCreds.length})
70	          </CardTitle>
71	          {canManualAdd && activeAction === null && (
72	            <Button
73	              size="sm"
74	              onClick={() => setActiveAction({ type: "add" })}
75	            >
