77	            </Button>
78	          )}
79	        </div>
80	      </CardHeader>
81	      <CardContent className="space-y-3">
82	        {activeAction?.type === "add" && (
83	          <AddCredentialForm
84	            tenantSlug={tenantSlug}
85	            memberId={memberId}
86	            availableFobs={availableFobs}
87	            allowFobCreationAtProgramming={allowFobCreationAtProgramming}
88	            memberAccessLevelName={memberAccessLevelName}
89	            accessLevels={accessLevels}
90	            onDone={() => {
91	              setActiveAction(null);
92	              router.refresh();
93	            }}
94	            onCancel={() => setActiveAction(null)}
95	          />
96	        )}
97	
98	        {activeAction?.type === "revoke" && (
99	          <RevokeCredentialForm
100	            tenantSlug={tenantSlug}
101	            credentialId={activeAction.credentialId}
102	            onDone={() => {
103	              setActiveAction(null);
104	              router.refresh();
105	            }}
106	            onCancel={() => setActiveAction(null)}
107	          />
108	        )}
109	
110	        {activeAction?.type === "swap" && (
111	          <SwapCredentialForm
112	            tenantSlug={tenantSlug}
113	            credentialId={activeAction.credentialId}
114	            availableFobs={availableFobs}
115	            allowFobCreationAtProgramming={allowFobCreationAtProgramming}
116	            onDone={() => {
117	              setActiveAction(null);
118	              router.refresh();
119	            }}
120	            onCancel={() => setActiveAction(null)}
121	          />
