123	
124	        {/* Active credentials with action buttons */}
125	        {activeCreds.length === 0 && inactiveCreds.length === 0 && activeAction === null && (
126	          <p className="text-sm text-muted-foreground">No credentials</p>
127	        )}
128	
129	        {activeAction === null &&
130	          activeCreds.map((c) => (
131	            <div
132	              key={c.id}
133	              className="flex items-center justify-between rounded border p-2 text-sm"
134	            >
135	              <Link
136	                href={`/t/${tenantSlug}/admin/fobs/${c.id}`}
137	                className="flex-1 transition-colors hover:text-primary"
138	              >
139	                <span className="font-medium">{c.credentialTypeName}</span>
140	                {c.serialNumber && (
141	                  <span className="ml-2 text-muted-foreground">
142	                    #{c.serialNumber}
143	                  </span>
144	                )}
