212	
213	/* --- Add Credential Form (simplified: just fob picker) --- */
214	
215	function AddCredentialForm({
216	  tenantSlug,
217	  memberId,
218	  availableFobs,
219	  allowFobCreationAtProgramming,
220	  memberAccessLevelName,
221	  accessLevels,
222	  onDone,
223	  onCancel,
224	}: {
225	  tenantSlug: string;
226	  memberId: string;
227	  availableFobs: AvailableFob[];
228	  allowFobCreationAtProgramming: boolean;
229	  memberAccessLevelName: string | null;
230	  accessLevels: IdName[];
231	  onDone: () => void;
232	  onCancel: () => void;
233	}) {
234	  const [selectedFobId, setSelectedFobId] = useState("");
235	  const [manualSerialNumber, setManualSerialNumber] = useState("");
236	  const [stage, setStage] = useState<"programming" | "pickup" | "issued">("programming");
237	  const [submitting, setSubmitting] = useState(false);
238	  const [error, setError] = useState<string | null>(null);
239	  const [manualAccessLevelId, setManualAccessLevelId] = useState("");
240	  const [manualExpiresAt, setManualExpiresAt] = useState("");
241	
242	  const selectedFob = selectedFobId
243	    ? availableFobs.find((f) => f.id === selectedFobId) ?? null
244	    : null;
245	  const effectiveSerial = selectedFob?.serialNumber ?? manualSerialNumber;
246	  const needsActivation = stage === "pickup" || stage === "issued";
247	  const noRuleMatch = !memberAccessLevelName;
248	  const showManualFields = needsActivation && noRuleMatch;
249	
250	  async function handleSubmit() {
251	    if (!effectiveSerial.trim()) return;
252	    if (showManualFields && !manualAccessLevelId) return;
253	    setSubmitting(true);
254	    setError(null);
255	
256	    try {
257	      const res = await fetch(`/api/v1/t/${tenantSlug}/credentials`, {
258	        method: "POST",
259	        headers: { "Content-Type": "application/json" },
260	        body: JSON.stringify({
261	          ownerId: memberId,
262	          serialNumber: effectiveSerial.trim(),
263	          credentialId: selectedFob?.id,
264	          credentialTypeId: selectedFob?.credentialTypeId,
265	          stage,
266	          ...(showManualFields && manualAccessLevelId ? { accessLevelId: manualAccessLevelId } : {}),
267	          ...(showManualFields && manualExpiresAt ? { expiresAt: manualExpiresAt } : {}),
268	        }),
269	      });
270	
271	      if (!res.ok) {
272	        const data = await res.json();
273	        throw new Error(data.error ?? "Failed to add credential");
274	      }
275	
276	      onDone();
277	    } catch (err) {
278	      setError(err instanceof Error ? err.message : "Something went wrong");
279	      setSubmitting(false);
280	    }
281	  }
282	
283	  return (
284	    <div className="space-y-3 rounded-lg border p-4">
285	      <p className="text-sm font-medium">Add Credential</p>
286	
287	      <FobPicker
288	        availableFobs={availableFobs}
289	        allowFobCreationAtProgramming={allowFobCreationAtProgramming}
290	        selectedFobId={selectedFobId}
291	        manualSerialNumber={manualSerialNumber}
292	        onSelect={(fob) => {
293	          setSelectedFobId(fob?.id ?? "");
294	          setManualSerialNumber("");
295	        }}
296	        onManualSerialChange={(v) => {
297	          setManualSerialNumber(v);
298	          setSelectedFobId("");
299	        }}
300	      />
301	
302	      {/* Reassignment warning */}
303	      {selectedFob?.previousOwnerName && (
304	        <p className="text-xs text-amber-600 rounded bg-amber-50 px-3 py-2">
305	          This fob was previously assigned to {selectedFob.previousOwnerName}. It will be reassigned to this member.
306	        </p>
307	      )}
308	
309	      <div className="space-y-2">
310	        <Label className="text-xs">Stage</Label>
311	        <div className="space-y-1">
312	          {[
313	            { value: "programming" as const, label: "Send for Programming", desc: "Credential needs to be programmed first" },
314	            { value: "pickup" as const, label: "Programmed - Ready for Pickup", desc: "Already programmed, waiting for member to collect" },
315	            { value: "issued" as const, label: "Programmed & Issued", desc: "Already programmed and handed to the member" },
316	          ].map((opt) => (
317	            <label key={opt.value} className="flex items-start gap-2 cursor-pointer rounded border p-2 hover:bg-accent/50">
318	              <input
319	                type="radio"
320	                name="stage"
321	                value={opt.value}
322	                checked={stage === opt.value}
323	                onChange={() => setStage(opt.value)}
324	                className="mt-0.5"
325	              />
326	              <div>
327	                <p className="text-sm font-medium">{opt.label}</p>
328	                <p className="text-xs text-muted-foreground">{opt.desc}</p>
329	              </div>
330	            </label>
331	          ))}
