251	          .where(eq(credentials.id, existingFob.id))
252	          .returning();
253	        credential = updated;
254	      } else {
255	        const [created] = await tx
256	          .insert(credentials)
257	          .values({
258	            tenantId: tenant.id,
259	            serialNumber,
260	            ...credValues,
261	          })
262	          .returning();
263	        credential = created;
264	      }
265	
266	      // Update membership access level if one was set (either from rules or manual)
267	      if (accessLevelId) {
268	        await tx
269	          .update(tenantMemberships)
270	          .set({ accessLevelId, updatedAt: now })
271	          .where(
272	            and(
273	              eq(tenantMemberships.userId, ownerId),
274	              eq(tenantMemberships.tenantId, tenant.id)
275	            )
276	          );
277	      }
278	
279	      // --- Audit entries ---
280	
281	      // 1. Reassignment audit (existing fob with different previous owner)
282	      if (wasReassignment) {
283	        await createAuditEntry(tx, {
284	          tenantId: tenant.id,
285	          entityType: AuditEntityType.CREDENTIAL,
286	          entityId: credential.id,
287	          action: AuditAction.STATUS_CHANGE,
288	          fromState: "deactivated",
289	          toState: credStatus,
290	          actorId: auth.user.id,
291	          actorType: "user",
292	          metadata: {
293	            description: "Credential reassigned",
294	            previousOwnerId,
295	            newOwnerId: ownerId,
296	            reason: "manual_add",
297	          },
298	        });
299	      }
300	
301	      // 2. Activation audit (pickup or issued)
302	      if (stage === "pickup" || stage === "issued") {
303	        await createAuditEntry(tx, {
304	          tenantId: tenant.id,
305	          entityType: AuditEntityType.CREDENTIAL,
306	          entityId: credential.id,
307	          action: wasReassignment
308	            ? AuditAction.UPDATE
309	            : AuditAction.STATUS_CHANGE,
310	          toState: CredentialStatus.ACTIVE,
311	          actorId: auth.user.id,
312	          actorType: "user",
313	          metadata: {
314	            description: "Credential activated",
315	            expiresAt: calculatedExpiresAt?.toISOString() ?? null,
316	            stage,
317	          },
318	        });
319	      }
320	
321	      // 3. New allocation audit (no existing fob - brand new credential)
322	      if (!existingFob) {
323	        await createAuditEntry(tx, {
324	          tenantId: tenant.id,
325	          entityType: AuditEntityType.CREDENTIAL,
326	          entityId: credential.id,
327	          action: AuditAction.CREATE,
328	          toState: credStatus,
329	          actorId: auth.user.id,
330	          actorType: "user",
331	          metadata: {
332	            description: "Credential assigned",
333	            ownerId,
334	            stage,
335	            serialNumber,
336	            credentialTypeId,
337	            accessLevelId: accessLevelId ?? null,
338	          },
339	        });
340	      }
341	
342	      // 4. Request audit entry
343	      const stageLabels: Record<string, string> = {
344	        programming: "Needs programming",
345	        pickup: "Programmed, awaiting pickup",
346	        issued: "Issued directly",
347	      };
348	      await createAuditEntry(tx, {
349	        tenantId: tenant.id,
350	        entityType: AuditEntityType.FOB_REQUEST,
351	        entityId: fobRequest.id,
352	        action: AuditAction.CREATE,
353	        toState: requestStatus,
354	        actorId: auth.user.id,
355	        actorType: "user",
356	        metadata: {
357	          action: "manual_add",
358	          credentialId: credential.id,
359	          serialNumber,
360	          credentialTypeName: ct.name,
361	          accessLevelName: accessLevelName ?? null,
362	          stage,
363	          stageDescription: stageLabels[stage] ?? stage,
364	        },
365	      });
366	
367	      return {
368	        credential,
369	        expiresAt: calculatedExpiresAt?.toISOString() ?? null,
370	        accessLevelName,
371	        wasReassignment,
372	      };
373	    });
374	
375	    return NextResponse.json(result, { status: 201 });
376	  },
377	  {}
378	);
