"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";

export type CredentialUpdateRowProps = {
  tenantSlug: string;
  credential: {
    id: string;
    serialNumber: string | null;
    credentialTypeName: string | null;
    programmingReason: string | null;
    ownerFirstName: string | null;
    ownerLastName: string | null;
  };
};

export function CredentialUpdateRow({ tenantSlug, credential }: CredentialUpdateRowProps) {
  const router = useRouter();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);

  async function confirm() {
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/v1/t/${tenantSlug}/credentials/${credential.id}/confirm-programming`,
        { method: "POST" }
      );
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error ?? "Failed to confirm");
      }
      setDone(true);
      setTimeout(() => router.refresh(), 800);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
      setSubmitting(false);
    }
  }

  if (done) return null;

  const owner = [credential.ownerFirstName, credential.ownerLastName]
    .filter(Boolean)
    .join(" ");

  return (
    <div className="flex items-center justify-between rounded-lg border border-amber-200 bg-white p-3 text-sm">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="font-medium">#{credential.serialNumber ?? "?"}</span>
          <span className="text-muted-foreground">{credential.credentialTypeName}</span>
          {owner && <span>{owner}</span>}
        </div>
        {credential.programmingReason && (
          <p className="text-xs text-muted-foreground mt-0.5">
            {credential.programmingReason}
          </p>
        )}
        {error && <p className="text-xs text-destructive mt-1">{error}</p>}
      </div>
      <div className="flex items-center gap-2 ml-3">
        <Link
          href={`/t/${tenantSlug}/admin/fobs/${credential.id}`}
          className="text-xs text-muted-foreground hover:text-primary hover:underline"
        >
          View
        </Link>
        <Button size="sm" onClick={confirm} disabled={submitting}>
          {submitting ? "..." : "Confirm Programmed"}
        </Button>
      </div>
    </div>
  );
}

