let body: z.infer<typeof cancelProgrammingSchema> = {};
try {
  const raw = await request.json();
  const parsed = cancelProgrammingSchema.safeParse(raw);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Validation failed", details: parsed.error.flatten() },
      { status: 400 }
    );
  }
  body = parsed.data;
} catch {
  // Empty body is allowed — reason is optional
}

const result = await withTenant(tenant.id, async (tx) => {
  const [cred] = await tx
    .select()
    .from(credentials)
    .where(
      and(
        eq(credentials.id, credentialId),
        eq(credentials.tenantId, tenant.id)
      )
    )
    .limit(1);

  if (!cred) return null;

  if (!cred.programmingRequired) {
    throw new Error("No pending update to cancel");
  }

  const now = new Date();
  const previousReason = cred.programmingReason;
  const discardedPendingExpiry = cred.pendingExpiresAt;

  await tx
    .update(credentials)
    .set({
      programmingRequired: false,
      programmingReason: null,
      programmingRequestedAt: null,
      pendingExpiresAt: null,
      updatedAt: now,
    })
    .where(eq(credentials.id, credentialId));

  await createAuditEntry(tx, {
    tenantId: tenant.id,
    entityType: AuditEntityType.CREDENTIAL,
    entityId: credentialId,
    action: AuditAction.UPDATE,
    actorId: auth.user.id,
    metadata: {
      action: "cancel_programming",
      previousReason,
      discardedPendingExpiresAt: discardedPendingExpiry?.toISOString() ?? null,
      reason: body.reason ?? null,
    },
  });

  return {
    ...cred,
    programmingRequired: false,
    programmingReason: null,
    programmingRequestedAt: null,
    pendingExpiresAt: null,
  };
});

if (!result) {
  return NextResponse.json(
    { error: "Credential not found" },
    { status: 404 }
  );
}

