type Stage = "programming" | "pickup" | "issued" | "expiry_update";
const [selectedFobId, setSelectedFobId] = useState("");
const [manualSerialNumber, setManualSerialNumber] = useState("");
const [stage, setStage] = useState<Stage>("programming");
const [submitting, setSubmitting] = useState(false);
const [error, setError] = useState<string | null>(null);
const [manualAccessLevelId, setManualAccessLevelId] = useState("");
const [manualExpiresAt, setManualExpiresAt] = useState("");

const isExpiryUpdate = stage === "expiry_update";
// The member's own expired/returned fobs are only re-attachable through the
// expiry update stage; the other stages would try to create them again.
const fobsForStage = isExpiryUpdate
  ? availableFobs
  : availableFobs.filter((f) => !f.ownedByThisMember);
const selectedFob = selectedFobId
  ? fobsForStage.find((f) => f.id === selectedFobId) ?? null
  : null;
const effectiveSerial = selectedFob?.serialNumber ?? manualSerialNumber;
const needsActivation = stage === "pickup" || stage === "issued";
const noRuleMatch = !memberAccessLevelName;
const showManualFields = (needsActivation || isExpiryUpdate) && noRuleMatch;

function changeStage(next: Stage) {
  setStage(next);
  if (next !== "expiry_update" && selectedFob?.ownedByThisMember) {
    setSelectedFobId("");
  }
}

