/**
 * Credential expiry for the current membership year (season convention:
 * 1 September). If the local date in the tenant's timezone is on or after
 * 1 July, the season being entered ends 1 September NEXT year; otherwise it
 * ends 1 September this year. Returned as midnight 1 September in the
 * tenant's timezone, stored as UTC.
 *
 * This is the single owner of the season rollover rule: credential expiry is
 * driven solely by the membership year (extended via renewal attestation /
 * confirm-programming), never by individual request flows.
 */
export function membershipYearExpiry(timezone: string, now: Date = new Date()): Date {
  const localNow = new Date(now.toLocaleString("en-US", { timeZone: timezone }));
  const year = localNow.getFullYear();
  const month = localNow.getMonth(); // 0-indexed, so July = 6
  return midnightInTimezone(month >= 6 ? year + 1 : year, 8, 1, timezone);
}

