"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

type AttestationRecord = {
};

export function AttestationSection({
  tenantSlug,
  userId,
  attestations,
  seasons,
  canRenew,
}: {
  tenantSlug: string;
  userId: string;
  attestations: AttestationRecord[];
  seasons: string[];
  canRenew: boolean;
}) {
  const router = useRouter();
  const [forceRenewOpen, setForceRenewOpen] = useState(false);
  const [season, setSeason] = useState("");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const pending = attestations.find((a) => a.status === "pending");
  const completed = attestations.filter((a) => a.status === "completed");

  async function handleResend() {
    // Re-send is just triggering the renew endpoint again with the same season
    if (!pending) return;
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/v1/t/${tenantSlug}/members/${userId}/renew`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ season: pending.season }),
        }
      );
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error ?? "Failed to re-send attestation");
      }
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setSubmitting(false);
    }
