p='apps/web/src/__tests__/manual-add-expiry-update.test.ts'
s=open(p).read()
assert 'ISC-163' not in s
new_cases='''  it("yes after the fob was reassigned is refused and the link stays usable for the admin to sort out (ISC-163)", async () => {
    const serial = `MOVED-${suffix}`;
    const cred = await seedCredential({ serial, ownerId: member.id, status: "expired" });
    expect((await stage(serial)).status).toBe(201);
    const [att] = await pendingScopedFor(cred.id);
    // Admin moves the fob to someone else before the member answers
    await db.update(credentials).set({ ownerId: otherMember.id }).where(eq(credentials.id, cred.id));

    const res = await attestationPost(att.token, [{ credentialId: cred.id, confirmed: true }]);
    expect(res.status).toBe(409);
    const after = await load(cred.id);
    expect(after.programmingRequired).toBe(false);
    expect(after.pendingExpiresAt).toBeNull();
    expect((await pendingScopedFor(cred.id))[0].status).toBe("pending");
  });

  it("an empty answer does not consume a scoped confirmation (ISC-164)", async () => {
    const serial = `EMPTY-${suffix}`;
    const cred = await seedCredential({ serial, ownerId: member.id, status: "expired" });
    expect((await stage(serial)).status).toBe(201);
    const [att] = await pendingScopedFor(cred.id);
    const res = await attestationPost(att.token, []);
    expect(res.status).toBe(400);
    expect((await pendingScopedFor(cred.id))[0].status).toBe("pending");
  });

  it("quotes the previous deactivation reason to the programmer when the member confirms (ISC-165)", async () => {
    const serial = `REASON-${suffix}`;
    const cred = await seedCredential({ serial, ownerId: member.id, status: "deactivated" });
    expect((await stage(serial)).status).toBe(201);
    // Still on the row while the member is being asked
    expect((await load(cred.id)).deactivationReason).toBe("Revoked");
    const [att] = await pendingScopedFor(cred.id);
    expect((await attestationPost(att.token, [{ credentialId: cred.id, confirmed: true }])).status).toBe(200);
    const after = await load(cred.id);
    expect(after.programmingReason).toContain("previously deactivated: Revoked");
    expect(after.deactivationReason).toBeNull();
    expect(after.deactivatedBy).toBeNull();
  });

  it("refuses to stage for a member with no email address (ISC-166)", async () => {
    const serial = `NOEMAIL-${suffix}`;
    const cred = await seedCredential({ serial, ownerId: noEmailMember.id, status: "expired" });
    const before = await load(cred.id);
    const { status, json } = await stage(serial, noEmailMember.id);
    expect(status).toBe(400);
    expect(json.error).toMatch(/no email address/);
    expect(await load(cred.id)).toEqual(before);
    expect(await pendingScopedFor(cred.id)).toHaveLength(0);
    expect(sentTemplates).toEqual([]);
  });

  it("admin can cancel a pending confirmation, which unlocks staging again (ISC-167)", async () => {
    const serial = `CANCEL-${suffix}`;
    const cred = await seedCredential({ serial, ownerId: member.id, status: "expired" });
    const first = await stage(serial);
    expect(first.status).toBe(201);
    const [att] = await pendingScopedFor(cred.id);

    const cancelled = await memberAction(cancelConfirmation, member.id, "cancel-confirmation", {
      attestationId: att.id,
      reason: "Wrong fob number",
    });
    expect(cancelled.status).toBe(200);
    const [row] = await db
      .select({ status: attestationRequests.status })
      .from(attestationRequests)
      .where(eq(attestationRequests.id, att.id));
    expect(row.status).toBe("cancelled");
    // The old link is dead
    expect((await attestationGet(att.token)).status).toBe(410);
    // Cancelling twice is refused
    expect((await memberAction(cancelConfirmation, member.id, "cancel-confirmation", { attestationId: att.id })).status).toBe(409);
    const credAudit = await auditRows(cred.id, "confirmation_cancelled");
    expect(credAudit).toHaveLength(1);
    expect((credAudit[0].metadata as Record<string, unknown>).reason).toBe("Wrong fob number");

    // Staging again now works and sends a fresh email
    sentTemplates.length = 0;
    const second = await stage(serial);
    expect(second.status).toBe(201);
    expect(sentTemplates).toEqual(["credentialHeldConfirmation"]);
    expect((await pendingScopedFor(cred.id)).map((r) => r.id)).toEqual([second.json.attestationId]);
  });

  it("admin can answer on the member's behalf: staged for the programmer, attestation completed, season untouched (ISC-168)", async () => {
    const serial = `BEHALF-${suffix}`;
